```js
await page.goto('/ops/radar');
await expect(page.getByRole('main')).toBeVisible();

// Tag the ops shell root: the closest ancestor of <main> that also contains the header/nav landmark.
await page.evaluate(() => {
  const main = document.querySelector('main, [role="main"]');
  const other = document.querySelector('header, [role="banner"], nav, [role="navigation"], aside');
  let el = main.parentElement;
  while (el && other && !el.contains(other)) el = el.parentElement;
  (el || main.parentElement).setAttribute('data-test-shell', '1');
});

const shell = page.locator('[data-test-shell="1"]');
await expect(shell).toHaveCSS('display', 'flex');
await expect(shell).toHaveCSS('flex-direction', 'column');
```
